"""
.. connect:: true  # EDGE
"""
import os
from pyspark.errors.exceptions.base import PySparkException  # Edge


# BEGIN EDGE
def _use_pyspark_pipelines_api() -> bool:
    """Whether ``pyspark.pipelines`` should expose the OSS API or fall back to ``dlt``."""
    if os.environ.get("TEST_ONLY_USE_PYSPARK_PIPELINES_API", "").lower() == "true":
        return True
    try:
        from dbruntime.safe import pysafex
    except ImportError:
        return False
    return pysafex("databricks.repl.python.enableServerlessGcStandaloneMvSt", False)


if _use_pyspark_pipelines_api():
    # END EDGE
    from pyspark.pipelines.api import (
        append_flow,
        table,
        materialized_view,
        temporary_view,
        create_streaming_table,
        create_sink,
    )

    __all__ = [
        "append_flow",
        "table",
        "materialized_view",
        "temporary_view",
        "create_streaming_table",
        "create_sink",
    ]
# BEGIN: EDGE
else:
    try:
        from dlt import *
    except ImportError:
        raise PySparkException(errorClass="PIPELINES_NOT_SUPPORTED")
# END: EDGE
